const html = items[0].json.body || '';
if (!html) return [];

function stripTags(s){ return s.replace(/<[^>]*>/g,'').replace(/&amp;/g,'&').replace(/&nbsp;/g,' ').trim(); }

const splitArticles = html.split(/<article[^>]*class="[^"]*Box-row[^"]*"[^>]*>/i).slice(1);
const repos = [];
for (let i = 0; i < Math.min(10, splitArticles.length); i++) {
  const block = splitArticles[i].split(/<\/article>/i)[0];

  const aMatch = block.match(/<h1[^>]*>[\s\S]*?<a[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/i);
  const href = aMatch ? aMatch[1].trim() : '';
  const rawName = aMatch ? aMatch[2] : '';
  const name = stripTags(rawName).replace(/\s+/g,' ').trim();

  const descMatch = block.match(/<p[^>]*>([\s\S]*?)<\/p>/i);
  const description = descMatch ? stripTags(descMatch[1]) : '';

  const langMatch = block.match(/itemprop="programmingLanguage"[^>]*>([^<]*)/i);
  const lang = langMatch ? langMatch[1].trim() : '';

  const starsMatch = block.match(/href="[^"]+\/stargazers"[^>]*>[\s\S]*?<\/a>\s*([0-9,\.KkMsm\s]*)/i) || block.match(/href="[^"]+\/stargazers"[^>]*>([\s\S]*?)<\/a>/i);
  let stars = '';
  if (starsMatch) stars = stripTags(starsMatch[1] || starsMatch[0]).replace(/\s+/g,' ').trim();

  const todayMatch = block.match(/(\d[0-9,\.KkMm]*)\s+stars?\s+today/i) || block.match(/<span[^>]*class="float-sm-right"[^>]*>([\s\S]*?)<\/span>/i);
  let todayStars = '';
  if (todayMatch) todayStars = stripTags(todayMatch[1] || todayMatch[0]).replace(/\s+/g,' ').trim();

  repos.push({
    rank: i+1,
    name: name || href.replace(/^\//,'') || 'unknown',
    url: href ? `https://github.com${href}` : '',
    description,
    lang,
    stars,
    todayStars
  });
}

return repos.map(r => ({ json: r }));

const top = items.map(it => it.json || {});
if (!top.length) return [{ json: { chatMessage: '*GitHub Trending — no results*' } }];
let text = '*GitHub Trending — top ' + top.length + '*\n\n';
top.forEach(r => {
  text += `${r.rank}. [${r.name}](${r.url})\n`;
  if (r.description) text += `_${r.description}_\n`;
  const meta = [];
  if (r.lang) meta.push(r.lang);
  if (r.stars) meta.push(`★ ${r.stars}`);
  if (r.todayStars) meta.push(`${r.todayStars} today`);
  if (meta.length) text += meta.join(' · ') + '\n';
  text += '\n';
});
return [{ json: { chatMessage: text } }];
